from typing import List
from fastapi import FastAPI, Depends, HTTPException, status
from fastapi.middleware.cors import CORSMiddleware
from sqlalchemy.orm import Session

from database import engine, Base, get_db
import models
import schemas

# Automatically create tables if they do not exist
Base.metadata.create_all(bind=engine)

# Initialize FastAPI application
app = FastAPI(
    title="SmartMandi Queue Manager API",
    description="Backend API for SIH26032 - Smart India Hackathon Procurement & Queue System",
    version="1.0.0"
)

# CORS Configuration
origins = [
    "http://localhost:5173",
    "http://127.0.0.1:5173",
]

app.add_middleware(
    CORSMiddleware,
    allow_origins=origins,
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


# --- Root & Health Endpoints ---
@app.get("/")
def read_root():
    return {"message": "Welcome to SmartMandi Queue Manager API"}


@app.get("/health")
def health_check(db: Session = Depends(get_db)):
    """Health check endpoint that verifies API & Database connectivity."""
    centers_count = db.query(models.Center).count()
    farmers_count = db.query(models.Farmer).count()
    bookings_count = db.query(models.Booking).count()

    return {
        "status": "online",
        "service": "SmartMandi Queue Manager",
        "message": "System Online",
        "database": "Connected",
        "stats": {
            "total_centers": centers_count,
            "total_farmers": farmers_count,
            "total_bookings": bookings_count
        }
    }


# --- Centers Endpoints ---
@app.get("/centers", response_model=List[schemas.CenterResponse])
def get_centers(db: Session = Depends(get_db)):
    """List all procurement centers."""
    return db.query(models.Center).all()


@app.post("/centers", response_model=schemas.CenterResponse, status_code=status.HTTP_201_CREATED)
def create_center(center: schemas.CenterCreate, db: Session = Depends(get_db)):
    """Create a new procurement center."""
    existing = db.query(models.Center).filter(models.Center.code == center.code).first()
    if existing:
        raise HTTPException(status_code=400, detail="Center code already registered.")
    new_center = models.Center(**center.model_dump())
    db.add(new_center)
    db.commit()
    db.refresh(new_center)
    return new_center


# --- Farmers Endpoints ---
@app.get("/farmers", response_model=List[schemas.FarmerResponse])
def get_farmers(skip: int = 0, limit: int = 50, db: Session = Depends(get_db)):
    """List farmers with pagination."""
    return db.query(models.Farmer).offset(skip).limit(limit).all()


@app.post("/farmers", response_model=schemas.FarmerResponse, status_code=status.HTTP_201_CREATED)
def create_farmer(farmer: schemas.FarmerCreate, db: Session = Depends(get_db)):
    """Register a new farmer."""
    existing = db.query(models.Farmer).filter(models.Farmer.phone_number == farmer.phone_number).first()
    if existing:
        raise HTTPException(status_code=400, detail="Farmer phone number already registered.")
    new_farmer = models.Farmer(**farmer.model_dump())
    db.add(new_farmer)
    db.commit()
    db.refresh(new_farmer)
    return new_farmer


# --- Bookings Endpoints ---
@app.get("/bookings", response_model=List[schemas.BookingResponse])
def get_bookings(db: Session = Depends(get_db)):
    """List all bookings with queue positions."""
    return db.query(models.Booking).all()


# --- Payments Endpoints ---
@app.get("/payments", response_model=List[schemas.PaymentResponse])
def get_payments(db: Session = Depends(get_db)):
    """List all payment records."""
    return db.query(models.Payment).all()

import { useState, useEffect } from "react";
import "./App.css";

function App() {
  const [healthStatus, setHealthStatus] = useState("Checking...");
  const [backendDetails, setBackendDetails] = useState(null);
  const [centers, setCenters] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [isOnline, setIsOnline] = useState(false);
  const [error, setError] = useState(null);
  const [activeTab, setActiveTab] = useState("overview");

  const fetchHealthAndData = async () => {
    setHealthStatus("Connecting...");
    setError(null);
    try {
      const response = await fetch("http://127.0.0.1:8000/health");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      if (data.status === "online") {
        setHealthStatus("System Online");
        setIsOnline(true);
        setBackendDetails(data);

        // Fetch Centers and Bookings
        const [centersRes, bookingsRes] = await Promise.all([
          fetch("http://127.0.0.1:8000/centers"),
          fetch("http://127.0.0.1:8000/bookings"),
        ]);

        if (centersRes.ok) {
          const centersData = await centersRes.json();
          setCenters(centersData);
        }
        if (bookingsRes.ok) {
          const bookingsData = await bookingsRes.json();
          setBookings(bookingsData);
        }
      } else {
        setHealthStatus("Unexpected Response");
        setIsOnline(false);
      }
    } catch (err) {
      console.error("Failed to connect to backend:", err);
      setHealthStatus("System Offline");
      setIsOnline(false);
      setError("Unable to connect to FastAPI backend at http://127.0.0.1:8000. Ensure the server is running.");
    }
  };

  useEffect(() => {
    fetchHealthAndData();
  }, []);

  return (
    <div className="container">
      <header className="header">
        <div className="badge">SIH26032 • Live System</div>
        <h1>🌾 SmartMandi Queue Manager</h1>
        <p className="subtitle">Real-time Grain Procurement & Smart Mandi Queue Management</p>
      </header>

      {/* Connectivity Banner */}
      <div className="card status-card">
        <div className="status-container">
          <span className={`status-indicator ${isOnline ? "online" : "offline"}`}></span>
          <span className="status-text">{healthStatus}</span>
          {backendDetails?.database && (
            <span className="db-badge">Database: {backendDetails.database}</span>
          )}
        </div>

        <button className="refresh-btn" onClick={fetchHealthAndData}>
          🔄 Refresh Live Data
        </button>
      </div>

      {error && (
        <div className="error-box">
          <p>{error}</p>
        </div>
      )}

      {/* Stats Counter Grid */}
      {backendDetails?.stats && (
        <div className="stats-grid">
          <div className="stat-card">
            <span className="stat-icon">🏛️</span>
            <span className="stat-value">{backendDetails.stats.total_centers}</span>
            <span className="stat-label">Procurement Centers</span>
          </div>
          <div className="stat-card">
            <span className="stat-icon">👨‍🌾</span>
            <span className="stat-value">{backendDetails.stats.total_farmers}</span>
            <span className="stat-label">Registered Farmers</span>
          </div>
          <div className="stat-card">
            <span className="stat-icon">📋</span>
            <span className="stat-value">{backendDetails.stats.total_bookings}</span>
            <span className="stat-label">Active Bookings</span>
          </div>
        </div>
      )}

      {/* Tab Navigation */}
      <div className="tabs">
        <button
          className={`tab-btn ${activeTab === "overview" ? "active" : ""}`}
          onClick={() => setActiveTab("overview")}
        >
          🏛️ Mandi Centers ({centers.length})
        </button>
        <button
          className={`tab-btn ${activeTab === "queue" ? "active" : ""}`}
          onClick={() => setActiveTab("queue")}
        >
          ⏱️ Live Queue ({bookings.length})
        </button>
      </div>

      {/* Tab Content: Centers */}
      {activeTab === "overview" && (
        <section className="card list-section">
          <h2>Haryana & Punjab Procurement Mandis</h2>
          <div className="items-grid">
            {centers.map((c) => (
              <div key={c.id} className="item-card">
                <div className="item-header">
                  <h3>{c.name}</h3>
                  <span className="code-pill">{c.code}</span>
                </div>
                <p className="item-location">📍 {c.district}, {c.state}</p>
                <div className="capacity-bar">
                  <span>Daily Capacity: <strong>{c.daily_capacity_quintals.toLocaleString()} Q</strong></span>
                  <span className="active-tag">{c.is_active ? "● Operational" : "Closed"}</span>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Tab Content: Live Queue */}
      {activeTab === "queue" && (
        <section className="card list-section">
          <h2>Active Farmer Queue Tokens</h2>
          <div className="table-wrapper">
            <table className="queue-table">
              <thead>
                <tr>
                  <th>Token #</th>
                  <th>Booking Ref</th>
                  <th>Date</th>
                  <th>Crop</th>
                  <th>Est. Quantity</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {bookings.map((b) => (
                  <tr key={b.id}>
                    <td><span className="token-badge">#{b.queue_number}</span></td>
                    <td className="mono">{b.booking_reference}</td>
                    <td>{b.booking_date}</td>
                    <td>{b.crop_type}</td>
                    <td><strong>{b.estimated_quantity_quintals} Q</strong></td>
                    <td>
                      <span className={`status-pill ${b.status.toLowerCase()}`}>
                        {b.status}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      )}

      <footer className="footer">
        <p>Smart India Hackathon • Project SIH26032</p>
        <p className="subtext">FastAPI + PostgreSQL / SQLite + React Vite</p>
      </footer>
    </div>
  );
}

