app = FastAPI(
    title="SmartMandi Queue Manager API",
    description="Backend API for SIH26032 - Smart India Hackathon Procurement & Queue System",
    version="1.0.0"
)

# CORS Configuration
origins = [
    "http://localhost:5173",
