}

.stat-num {
  font-size: 1.9rem;
  font-weight: 800;
  color: #f8fafc;
  line-height: 1;
}

.stat-lbl {
  font-size: 0.78rem;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* Table Card */
.table-card {
  background: #111827;
  border: 1px solid #1e293b;
  border-radius: 16px;
  overflow: hidden;
  flex: 1;
}

.table-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid #1e293b;
}

.table-header h2 {
  margin: 0;
  font-size: 1rem;
  font-weight: 600;
  color: #cbd5e1;
}

.queue-count {
  font-size: 0.8rem;
  color: #475569;
  background: #1e293b;
  padding: 0.2rem 0.6rem;
  border-radius: 9999px;
}

/* Table */
.table-wrapper {
  overflow-x: auto;
}

.queue-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
}

.queue-table th {
  background: #0f172a;
  color: #64748b;
  padding: 0.75rem 1rem;
  text-align: left;
  font-weight: 600;
  text-transform: uppercase;
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  border-bottom: 1px solid #1e293b;
